Here is a minimal working example using `ServerUtility::send_status_text()`. It connects to a vehicle (or sim), waits for a system, then sends a `STATUSTEXT` every second for 10 seconds. QGC will show the message in the HUD.

```cpp
// statustext_hello/statustext_hello.cpp
//
// Minimal example: send STATUSTEXT to QGC via ServerUtility.
//
// Run against sim:
//   ./statustext_hello udpin://0.0.0.0:14540
//
// Run against real vehicle (companion computer on serial):
//   ./statustext_hello serial:///dev/ttyUSB0:57600

#include <chrono>
#include <iostream>
#include <thread>

#include <mavsdk/mavsdk.hpp>
#include <mavsdk/plugins/server_utility/server_utility.hpp>

using namespace mavsdk;
using std::chrono::seconds;
using std::this_thread::sleep_for;

int main(int argc, char** argv)
{
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <connection_url>\n";
        return 1;
    }

    // Run as a companion-computer component so STATUSTEXT appears as a
    // separate MAVLink source in the GCS (not as the GCS talking to itself).
    Mavsdk mavsdk{Mavsdk::Configuration{ComponentType::CompanionComputer}};

    if (mavsdk.add_any_connection(argv[1]) != ConnectionResult::Success) {
        std::cerr << "Connection failed\n";
        return 1;
    }

    std::cout << "Waiting for vehicle..." << std::flush;
    while (mavsdk.systems().empty()) {
        sleep_for(std::chrono::milliseconds(100));
        std::cout << . << std::flush;
    }
    std::cout << n;

    auto system = mavsdk.systems().front();
    ServerUtility server_utility{system};

    for (int i = 0; i < 10; ++i) {
        const std::string msg = "Hello from MAVSDK (" + std::to_string(i + 1) + "/10)";
        const auto result = server_utility.send_status_text(
            ServerUtility::StatusTextType::Info, msg);
        std::cout << "send_status_text: " << result << "  \"" << msg << "\"\n";
        sleep_for(seconds(1));
    }

    return 0;
}
```

CMakeLists.txt:
```cmake
cmake_minimum_required(VERSION 3.10.2)
project(statustext_hello)
set(CMAKE_CXX_STANDARD 20)
find_package(MAVSDK REQUIRED)
add_executable(statustext_hello statustext_hello.cpp)
target_link_libraries(statustext_hello MAVSDK::mavsdk)
```

Build and run:
```sh
cmake -Bbuild -H. && cmake --build build
./build/statustext_hello udpin://0.0.0.0:14540
```

A few notes:
- `send_status_text()` handles chunking internally for messages longer than 50 bytes, matching the MAVLink spec.
- Using `ComponentType::CompanionComputer` means QGC shows the source as a companion computer rather than a GCS.
- If your app already has a MAVSDK instance talking to the vehicle, just reuse that `system` object — no second MAVSDK instance needed.

